    "unit_id": "BLLD_45-2019.D48.K1.a",
    "tieu_de_dieu": "Trách nhiệm khi chấm dứt hợp đồng lao động",
    "khoan_cha": "Trong thời hạn 14 ngày làm việc kể từ ngày chấm dứt hợp đồng lao động, hai bên có trách nhiệm thanh toán đầy đủ các khoản tiền có liên quan đến quyền lợi của mỗi bên, trừ trường hợp sau đây có thể kéo dài nhưng không được quá 30 ngày:",
    "chu_don_vi": "Người sử dụng lao động không phải là cá nhân chấm dứt hoạt động;"
   },
   "b": {
    "unit_id": "BLLD_45-2019.D156.K7",
    "tieu_de_dieu": "Các trường hợp giấy phép lao động hết hiệu lực",
    "khoan_cha": "",
    "chu_don_vi": "Doanh nghiệp, tổ chức, đối tác phía Việt Nam hoặc tổ chức nước ngoài tại Việt Nam sử dụng lao động là người nước ngoài chấm dứt hoạt động."
   },
   "vi_tu_chung": [
    "cease_operations"
   ]
  },
  {
   "cap_id": "P0151",
   "a": {
    "unit_id": "BLLD_45-2019.D48.K2",
    "tieu_de_dieu": "Trách nhiệm khi chấm dứt hợp đồng lao động",
    "khoan_cha": "",
    "chu_don_vi": "Tiền lương, bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp, trợ cấp thôi việc và các quyền lợi khác của người lao động theo thỏa ước lao động tập thể, hợp đồng lao động được ưu tiên thanh toán trong trường hợp doanh nghiệp, hợp tác xã bị chấm dứt hoạt động, bị giải thể, phá sản."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D80.K2",
    "tieu_de_dieu": "Thực hiện thỏa ước lao động tập thể doanh nghiệp trong trường hợp chia, tách, hợp nhất, sáp nhập; bán, cho thuê, chuyển đổi loại hình doanh nghiệp; chuyển nhượng quyền sở hữu, quyền sử dụng tài sản của doanh nghiệp",
    "khoan_cha": "",
    "chu_don_vi": "Trường hợp thỏa ước lao động tập thể doanh nghiệp hết hiệu lực do người sử dụng lao động chấm dứt hoạt động thì quyền lợi của người lao động được giải quyết theo quy định của pháp luật."
   },
   "vi_tu_chung": [
    "cease_operations"
   ]
  },
